#include <iostream>
#include <map>
#include <string>
using namespace std;

int main() {
    map<string, int> fish;
    fish["{w1}"] = 3;
    fish["{w2}"] = 5;

    if (fish.count("{w3}") > 0) {
        cout << "有喵" << endl;
    } else {
        cout << "没有喵" << endl;
    }
    cout << fish.size() << endl;
    return 0;
}
